#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int *data;
    int size;
    int capacity;
} DynamicArray;

void init_array(DynamicArray *arr) {
    arr->capacity = 2;
    arr->size = 0;
    arr->data = (int *)malloc(arr->capacity * sizeof(int));
}

void push(DynamicArray *arr, int val) {
    if (arr->size == arr->capacity) {
        arr->capacity *= 2;
        int *new_data = (int *)realloc(arr->data, arr->capacity * sizeof(int));
        if (new_data != NULL) {
            arr->data = new_data;
        }
    }
    arr->data[arr->size++] = val;
}

void pop(DynamicArray *arr) {
    if (arr->size == 0) {
        printf("EMPTY\n");
        return;
    }
    int val = arr->data[--arr->size];
    printf("%d\n", val);
    if (arr->size > 0 && arr->size <= arr->capacity / 4 && arr->capacity / 2 >= 2) {
        arr->capacity /= 2;
        int *new_data = (int *)realloc(arr->data, arr->capacity * sizeof(int));
        if (new_data != NULL) {
            arr->data = new_data;
        }
    }
}

void get(DynamicArray *arr, int idx) {
    if (idx < 0 || idx >= arr->size) {
        printf("OUT_OF_BOUNDS\n");
    } else {
        printf("%d\n", arr->data[idx]);
    }
}

void print_size(DynamicArray *arr) {
    printf("%d %d\n", arr->size, arr->capacity);
}

void free_array(DynamicArray *arr) {
    if (arr->data != NULL) {
        free(arr->data);
        arr->data = NULL;
    }
    arr->size = 0;
    arr->capacity = 0;
}

