#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *buffer;
    int length;
    int capacity;
} StringBuilder;

void sb_init(StringBuilder *sb) {
    sb->capacity = 8;
    sb->length = 0;
    sb->buffer = (char *)malloc(sb->capacity * sizeof(char));
    sb->buffer[0] = '\0';
}

void sb_ensure_capacity(StringBuilder *sb, int needed) {
    if (needed > sb->capacity) {
        while (sb->capacity < needed) {
            sb->capacity *= 2;
        }
        sb->buffer = (char *)realloc(sb->buffer, sb->capacity * sizeof(char));
    }
}

void sb_append(StringBuilder *sb, const char *str) {
    int add_len = (int)strlen(str);
    sb_ensure_capacity(sb, sb->length + add_len + 1);
    memcpy(sb->buffer + sb->length, str, add_len);
    sb->length += add_len;
    sb->buffer[sb->length] = '\0';
}

void sb_insert(StringBuilder *sb, int idx, const char *str) {
    if (idx < 0 || idx > sb->length) {
        printf("OUT_OF_BOUNDS\n");
        return;
    }
    int add_len = (int)strlen(str);
    sb_ensure_capacity(sb, sb->length + add_len + 1);
    memmove(sb->buffer + idx + add_len, sb->buffer + idx, sb->length - idx + 1);
    memcpy(sb->buffer + idx, str, add_len);
    sb->length += add_len;
}

void sb_delete(StringBuilder *sb, int start, int len) {
    if (start < 0 || start >= sb->length || len <= 0) {
        printf("OUT_OF_BOUNDS\n");
        return;
    }
    int del_count = len;
    if (start + del_count > sb->length) {
        del_count = sb->length - start;
    }
    memmove(sb->buffer + start, sb->buffer + start + del_count, sb->length - (start + del_count) + 1);
    sb->length -= del_count;
}

void sb_print(StringBuilder *sb) {
    printf("%s\n", sb->buffer);
}

void sb_info(StringBuilder *sb) {
    printf("LEN: %d CAP: %d\n", sb->length, sb->capacity);
}

void sb_free(StringBuilder *sb) {
    if (sb->buffer) {
        free(sb->buffer);
        sb->buffer = NULL;
    }
    sb->length = 0;
    sb->capacity = 0;
}

