    pool->total_blocks = pool_size / block_size;
    pool->used_count = 0;
    pool->used = (int *)calloc(pool->total_blocks, sizeof(int));
}

void pool_alloc(MemoryPool *pool) {
    if (pool->used_count >= pool->total_blocks) {
        printf("-1\n");
        return;
    }
    for (int i = 0; i < pool->total_blocks; i++) {
        if (!pool->used[i]) {
            pool->used[i] = 1;
            pool->used_count++;
            printf("%d\n", i);
            return;
        }
    }
    printf("-1\n");
}

void pool_free(MemoryPool *pool, int idx) {
