    sb->buffer = NULL;
    sb->size = 0;
    sb->max_mem = max_mem;
}

void sb_resize(SafeBuffer *sb, int new_size) {
    if (new_size < 0 || new_size > sb->max_mem) {
        printf("RESIZE_FAILED\n");
        return;
    }
    if (new_size == 0) {
        if (sb->buffer) {
            free(sb->buffer);
            sb->buffer = NULL;
        }
        sb->size = 0;
        printf("BUFFER_FREED\n");
        return;
    }
    unsigned char *temp = (unsigned char *)realloc(sb->buffer, new_size * sizeof(unsigned char));
    if (temp == NULL) {
        printf("RESIZE_FAILED\n");
        return;
    }
    sb->buffer = temp;
    if (new_size > sb->size) {
        memset(sb->buffer + sb->size, 0, new_size - sb->size);
    }
    sb->size = new_size;
    printf("RESIZED %d\n", new_size);
}

void sb_set(SafeBuffer *sb, int offset, int val) {
    if (offset < 0 || offset >= sb->size) {
        printf("OUT_OF_BOUNDS\n");
