    st->capacity = 2;
    st->size = 0;
    st->data = (int *)malloc(st->capacity * sizeof(int));
}

void stack_push(DynamicStack *st, int val) {
    if (st->size == st->capacity) {
        st->capacity *= 2;
        int *new_data = (int *)realloc(st->data, st->capacity * sizeof(int));
        if (new_data) {
