#include <string.h>

typedef struct {
    int id;
    int bytes;
} BlockEntry;

typedef struct {
    BlockEntry *blocks;
    int count;
    int capacity;
} LeakDetector;

void detector_init(LeakDetector *ld) {
    ld->capacity = 16;
    ld->count = 0;
    ld->blocks = (BlockEntry *)malloc(ld->capacity * sizeof(BlockEntry));
}

int find_block(LeakDetector *ld, int id) {
    for (int i = 0; i < ld->count; i++) {
        if (ld->blocks[i].id == id) return i;
    }
    return -1;
}

void detector_alloc(LeakDetector *ld, int id, int bytes) {
    if (bytes <= 0) {
        printf("ERROR_INVALID_SIZE\n");
        return;
    }
    if (find_block(ld, id) != -1) {
        printf("ERROR_DUPLICATE_ID %d\n", id);
        return;
    }
    if (ld->count == ld->capacity) {
        ld->capacity *= 2;
        ld->blocks = (BlockEntry *)realloc(ld->blocks, ld->capacity * sizeof(BlockEntry));
    }
    ld->blocks[ld->count].id = id;
    ld->blocks[ld->count].bytes = bytes;
    ld->count++;
    printf("ALLOCATED %d %d\n", id, bytes);
}

void detector_free(LeakDetector *ld, int id) {
    int idx = find_block(ld, id);
    if (idx == -1) {
        printf("ERROR_DOUBLE_OR_INVALID_FREE %d\n", id);
        return;
    }
    for (int i = idx; i < ld->count - 1; i++) {
        ld->blocks[i] = ld->blocks[i + 1];
    }
    ld->count--;
    printf("FREED %d\n", id);
}

void detector_active(LeakDetector *ld) {
    long long total_bytes = 0;
    for (int i = 0; i < ld->count; i++) {
        total_bytes += ld->blocks[i].bytes;
    }
    printf("ACTIVE_COUNT: %d ACTIVE_BYTES: %lld\n", ld->count, total_bytes);
}

int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

void detector_audit(LeakDetector *ld) {
    if (ld->count == 0) {
        printf("AUDIT_CLEAN: NO LEAKS\n");
        return;
    }
    long long total_bytes = 0;
    int *ids = (int *)malloc(ld->count * sizeof(int));
    for (int i = 0; i < ld->count; i++) {
        total_bytes += ld->blocks[i].bytes;
        ids[i] = ld->blocks[i].id;
    }
    qsort(ids, ld->count, sizeof(int), cmp_int);
    printf("AUDIT_LEAK: %lld BYTES IN %d BLOCKS\n", total_bytes, ld->count);
    for (int i = 0; i < ld->count; i++) {
        printf("%d%s", ids[i], (i == ld->count - 1) ? "" : " ");
    }
    printf("\n");
    free(ids);
}

void detector_destroy(LeakDetector *ld) {
    if (ld->blocks) {
        free(ld->blocks);
        ld->blocks = NULL;
    }
    ld->count = 0;
    ld->capacity = 0;
}

